<?php
require_once __DIR__ . '/../../includes/auth.php';
requireLogin();
$pdo = getDbConnection();
$status = $_GET['status'] ?? '';
if (!in_array($status, ['pending', 'verified', 'rejected'], true)) $status = '';
$sql = 'SELECT p.*, b.invoice_number, b.amount AS invoice_amount, c.full_name, c.account_number FROM payments p JOIN billing b ON b.id = p.billing_id JOIN customers c ON c.id = b.customer_id';
$parameters = [];
if ($status) { $sql .= ' WHERE p.verification_status = ?'; $parameters[] = $status; }
$sql .= ' ORDER BY p.created_at DESC';
$stmt = $pdo->prepare($sql); $stmt->execute($parameters); $payments = $stmt->fetchAll();
$pageTitle = 'Payments';
include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="mb-0">Payment Management</h3><small class="text-muted">Record, verify, and track payments against customer invoices.</small></div><a href="add.php" class="btn btn-primary"><i class="bi bi-plus-lg"></i> Record Payment</a></div>
<?php if (!empty($_GET['msg'])): ?><div class="alert alert-success alert-dismissible fade show"><?= htmlspecialchars($_GET['msg']) ?><button type="button" class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?>
<form method="get" class="d-flex gap-2 mb-3" style="max-width:360px;"><select name="status" class="form-select"><option value="">All verification statuses</option><?php foreach (['pending', 'verified', 'rejected'] as $option): ?><option value="<?= $option ?>" <?= $status === $option ? 'selected' : '' ?>><?= ucfirst($option) ?></option><?php endforeach; ?></select><button class="btn btn-outline-secondary">Filter</button></form>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead class="table-light"><tr><th>Date</th><th>Invoice</th><th>Customer</th><th>Amount</th><th>Method</th><th>Reference / Proof</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= date('M j, Y', strtotime($payment['payment_date'])) ?></td><td><?= htmlspecialchars($payment['invoice_number']) ?></td><td><div><?= htmlspecialchars($payment['full_name']) ?></div><small class="text-muted"><?= htmlspecialchars($payment['account_number']) ?></small></td><td>PHP <?= number_format((float) $payment['amount_paid'], 2) ?></td><td><?= htmlspecialchars($payment['payment_method']) ?></td><td><?= htmlspecialchars($payment['reference_number'] ?: ($payment['payment_method'] === 'Cash' ? 'Not required (cash)' : '-')) ?><?php if ($payment['proof_of_payment']): ?><br><a href="/<?= htmlspecialchars($payment['proof_of_payment']) ?>" target="_blank" rel="noopener">View proof</a><?php endif; ?></td><td><span class="badge bg-<?= $payment['verification_status'] === 'verified' ? 'success' : ($payment['verification_status'] === 'rejected' ? 'danger' : 'warning text-dark') ?>"><?= ucfirst(htmlspecialchars($payment['verification_status'])) ?></span></td><td class="text-end"><?php if ($payment['verification_status'] === 'pending'): ?><form action="verify.php" method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $payment['id'] ?>"><button class="btn btn-sm btn-success" name="action" value="verified"><?= $payment['payment_method'] === 'Cash' ? 'Confirm Cash Received' : 'Verify Transaction' ?></button><button class="btn btn-sm btn-outline-danger" name="action" value="rejected">Reject</button></form><?php elseif ($payment['verification_status'] === 'verified'): ?><a class="btn btn-sm btn-outline-primary" href="receipt.php?id=<?= $payment['id'] ?>">Receipt</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$payments): ?><tr><td colspan="8" class="text-center text-muted py-4">No payments found.</td></tr><?php endif; ?></tbody></table></div></div>
<?php include __DIR__ . '/../../includes/footer.php'; ?>
